window.__posterData({"id": "amira", "name": "Amira Smith", "folder": "CC_WEEK44_AMIRA", "v": "2", "scripts": ["https://cdn.jsdelivr.net/npm/p5@2.3.4/lib/p5.js", "https://cdn.jsdelivr.net/npm/p5.sound@0.4.1/dist/p5.sound.min.js"], "links": [], "css": "html, body {\n  margin: 0;\n  padding: 0;\n}\ncanvas {\n  display: block;\n}\n", "code": "let img;  //hämtar bilderna,bakgrundsbilden\nlet img2; //bild på stjärnan\nlet trail = [];       //punkter i musspåret\nlet starAngle = 0;    //stjärnans nuvarande rotation\nlet starSpeed = 0.01; //stjärnans nuvarande hastighet\n\nasync function setup() {\n  createCanvas(600, 800);\n\n  //behövde ändra till safeload då bilderna inte hämtades av någon anledning?. detta Laddar varje bild för sig, så att en bild som saknas inte stoppar allt\n  img = await safeLoad(\"ravebackground1.jpg\");\n  img2 = await safeLoad(\"mariostar.png\");\n}\n\n// Returnerar null istället för att krascha om bilden inte kan laddas\nasync function safeLoad(path) {\n  try {\n    return await loadImage(path);\n  } catch (e) {\n    console.log(\"Kunde inte ladda: \" + path);\n    return null;\n  }\n}\n\nfunction draw() {\n  background(0);\n\n  //BAKGRUND\n  if (img) image(img, 0, 0, 600, 800);\n\n//Här bad jag claude att skapa discostrålar som skjöts från högra hörnet. Eftersom det kändes relativt tomt och saknade rörelse\n //DISCOSTRÅLAR som skjuts ut från högra hörnet\n  push();\n  colorMode(HSB, 360, 100, 100, 255);\n  noStroke();\n\n  let rays = 8;       //detta motsvarar antal strålar\n  let rayLen = 1100;  //längdden på raysen\n  let spread = 0.05;  //bredden på raysen\n  let ox = 600;       //att de börjar från höger sidan \n  let oy = 0;         //översta kanten\n\n  for (let i = 0; i < rays; i++) {\n    //Solfjäder mellan rakt ner (PI*0.5) och rakt åt vänster (PI)\n    //AI kommentar ovan, vet ej vad som menas med solfjäder tror strålarna nedåt\n    let base = map(i, 0, rays - 1, PI * 0.55, PI * 0.95);\n\n    //dessa funktioner nedan gör så at strålarna svajar lite fram\n    let angle = base + sin(frameCount * 0.03 + i) * 0.08;\n\n    fill((i * 45 + frameCount) % 360, 60, 100, 90);\n\n    triangle(\n      ox, oy,\n      ox + cos(angle - spread) * rayLen, oy + sin(angle - spread) * rayLen,\n      ox + cos(angle + spread) * rayLen, oy + sin(angle + spread) * rayLen\n    );\n  }\n  pop();\n\n  //NEONPRICKAR som rör sig upp och ner\n  push();\n  noStroke();\n  fill(0, 255, 255);\n  for (let i = 0; i < 12; i++) {\n    let y = 680 + sin(frameCount * 0.02 + i) * 30;\n    let x = 40 + i * 55 + sin(frameCount * 0.03 + i) * 15;\n    circle(x, y, 8);\n  }\n  pop();\n\n  // prompt: jag vill att stjärnan snurrar snabbare när musen är nära själva stjärnan\n  // AI KOD STJÄRNANS HASTIGHET: snabbare när musen är nära mitten (300, 400)\n  let d = dist(mouseX, mouseY, 300, 400);\n  let targetSpeed = map(d, 0, 300, 0.12, 0.01, true);\n  starSpeed = lerp(starSpeed, targetSpeed, 0.05); // mjuk förändring\n  starAngle += starSpeed; //detta snurrar stjärnan lite snabbare till varje frame\n\n  //STJÄRNAN I MITTEN\n  //prompt: kan stjärnan pulsera när man klickar den, samt kan vi lägga till att själva stjärnan ändrar färg?\n  push();\n  translate(300, 400);\n  rotate(starAngle);\n  imageMode(CENTER);\n\n  \n  // AI KOD Puls: växer och krymper\n  let pulse = 400 + sin(frameCount * 0.08) * 25;\n\n  // Klickeffekt: större när man klickar\n  if (mouseIsPressed) {\n    pulse += 50;\n  }\n\n  //AI KODRegnbågsfärger\n  //Tint färgar själva bilden. den fungerar med hsb så den går runt färghjulet, förklarar hur stjärnan smidigt ändrar färg\n  colorMode(HSB, 360, 100, 100);\n  tint((frameCount * 2) % 360, 50, 100);\n\n  if (img2) image(img2, 0, 0, pulse, pulse);\n  noTint();\n  pop();\n\n\n  //promt: kan du göra en equalizer längst ner som ser ut som en ljudvisualisering? gärna med samma regnbågsfärger som tidigare\n  push();\n  colorMode(HSB, 360, 100, 100);\n  noStroke();\n\n  let barCount = 30; //antalet staplar\n  let barWidth = width / barCount; //widhten mellan staplarna\n\n  for (let i = 0; i < barCount; i++) {\n    // AI KOD noise() ger slumpmässiga men mjuka värden (mellan 0 och 1),\n    let n = noise(i * 0.3, frameCount * 0.06);\n     // gör om noise-värdet till en höjd mellan 5 och 50 pixlar\n    let h = constrain(map(n, 0.2, 0.8, 5, 50), 5, 50);\n    fill((i * 12 + frameCount) % 360, 80, 100);\n    // ritas från botten (height - h) så att staplarna växer uppåt\n    rect(i * barWidth + 2, height - h, barWidth - 4, h);\n  }\n  pop();\n\n  //texter\n  //prompt:Kan du lägga till texten RAAAAVE som skakar och har neonglöd,\n  // mitt namn under och en liten text längst ner?\n  push();\n  noStroke();\n  textAlign(LEFT);\n  textFont(\"trebuchet MS\");\n  textSize(85);\n\n  //Skakeffekt\n  //randimt flyttar texten en liten bit slumpmässigt varje frame som går\n  let tx = 10 + random(-2, 2);\n  let ty = 75 + random(-2, 2);\n\n  // AI KOD Neonglöd runt rubriken\n  drawingContext.shadowBlur = 30;\n  drawingContext.shadowColor = \"rgb(255, 0, 200)\";\n\n  fill(255, 0, 200);\n  text(\"RAAAAVE\", tx, ty);\n  fill(255, 150, 230); // ljusare kärna\n  text(\"RAAAAVE\", tx, ty);\n\n  // ai kod Stänger av glöden för resten av texterna\n  drawingContext.shadowBlur = 0;\n\n  fill(255);\n  textSize(22);\n  text(\"AMIRA SMITH\", 20, 100);\n\n  fill(0, 255, 255);\n  textSize(16);\n  text(\"FEEL THE FREQUENCY\", 30, 750);\n  pop();\n\n  //interaktiva delen färgglatt spår som följer musen\n  //promt: istället för den gula pricken, så vill jag ha en interaktiv del där ett färgglatt spår följer. gärna regnbågsfärgat\n  // AI KOD musen och blir större när man håller ner knappen.\n  if (mouseX !== pmouseX || mouseY !== pmouseY) {\n    trail.push({\n      x: mouseX,\n      y: mouseY,\n      life: 255,                     // AI KOD 255 = full synlighet, minskar till 0\n      hue: (frameCount * 5) % 360,   //färgen skiftar över tid\n      size: mouseIsPressed ? 60 : 30 //större spår vid klick\n    });\n  }\n\n  push();\n  colorMode(HSB, 360, 100, 100, 255);\n  noStroke();\n\n  //AI KOD, fattar ej med att loopa baklänges dock. Loopar baklänges så att vi kan ta bort punkter utan att hoppa över några\n  // (om man tar bort framifrån flyttas alla andra ett steg och en missas)\n  for (let i = trail.length - 1; i >= 0; i--) {\n    let t = trail[i];\n// life styr också genomskinligheten, så punkten tonar ut\n    fill(t.hue, 80, 100, t.life);\n    circle(t.x, t.y, 10 + (t.life / 255) * t.size);\n\n    t.life -= 6; // högre = kortare spår\n\n    if (t.life <= 0) {\n      trail.splice(i, 1);\n    }\n  }\n  pop();\n}", "assets": {"ravebackground1.jpg": {"mime": "image/webp", "b64": ""}, "mariostar.png": {"mime": "image/webp", "b64": ""}}});
